```
def is_prime(n):
 if n <= 1:
 return False
 for i in range(2, int(n**0.5) + 1):
 if n % i == 0:
 return False
 return True
def count_divisible_by_primes(numbers):
 prime_counts = {}
 total_primes = 0
 for num in numbers:
 if is_prime(num):
 total_primes += 1
 else:
 for i in range(2, num):
 if is_prime(i) and num % i == 0:
 prime_counts[i] = prime_counts.get(i, 0) + 1
 return prime_counts, total_primes
```
