let textAttributes = [NSAttributedString.Key.font: font]
let pageSize = CGSize(width: 300, height: 792) // 300 is the page width, 792 is the page height
// calculate the page count for each chapter
var chapterPageCounts = [String: Int]()
for (chapterTitle, chapterText) in chapters {
 let chapterSize = (chapterText as NSString).boundingRect(with: pageSize, options: .usesLineFragmentOrigin, attributes: textAttributes, context: nil).size
