Here's a sample Swift code for implementing a band-pass filter:
```swift
import Accelerate
func applyBandPassFilter(to signal: [Float], withCenterFrequency centerFrequency: Float, andBandwidth bandwidth: Float) -> [Float] {
 let nyquist = Float(NyquistFrequency)
 let freqRatio = centerFrequency / nyquist
 let bwRatio = bandwidth / nyquist

 let biquadFilter = BiquadFilter(b0: 0, b1: 0, b2: 0, a1: 0, a2: 0)
 let coefficients = biquadFilter.coefficients(for: .bandPass, withCenterFrequency: freqRatio, andBandwidth: bwRatio)

 var inputReal = [Float](repeating: 0, count: signal.count)
 var inputImaginary = [Float](repeating: 0, count: signal.count)

 for i in 0..<signal.count {
 inputReal[i] = signal[i]
 }

 var outputReal = [Float](repeating: 0, count: signal.count)
 var outputImaginary = [Float](repeating: 0, count: signal.count)

 vDSP_deq22D(&inputReal, vDSP_Stride(1), &inputImaginary, vDSP_Stride(1), &outputReal, vDSP_Stride(1), &outputImaginary, vDSP_Stride(1), vDSP_Length(signal.count), coefficients)

 return outputReal
}
```
