Here is an example code:
struct LexicalEntry {
 string name;
 string description;
 string category;
 bool operator==(const LexicalEntry& other) const {
 return (name == other.name && description == other.description && category == other.category);
 }
};
struct TourismExcursion {
 string location;
 int duration;
 double cost;
 bool operator==(const TourismExcursion& other) const {
 return (location == other.location && duration == other.duration && cost == other.cost);
 }
};
class ExcursionPlanner {
private:
 vector lexicon;
 vector excursions;
public:
 // Functions for adding and removing entries and excursions
 void addLexiconEntry(const LexicalEntry& entry) {
 lexicon.push_back(entry);
 }
 void removeLexiconEntry(const LexicalEntry& entry) {
 lexicon.erase(remove(lexicon.begin(), lexicon.end(), entry), lexicon.end());
 }
 void addExcursion(const TourismExcursion& excursion) {
 excursions.push_back(excursion);
 }
 void removeExcursion(const TourismExcursion& excursion) {
 excursions.erase(remove(excursions.begin(), excursions.end(), excursion), excursions.end());
 }
 // Function for finding excursions based on the attributes of the lexical entries
 vector findExcursionsByAttributes(const vector& attributes) const {
 vector matchingExcursions;
 for (const auto& excursion : excursions) {
 bool isMatch = true;
 for (const auto& attribute : attributes) {
 bool hasAttribute = false;
 for (const auto& entry : lexicon) {
 if (entry.name == attribute || entry.description == attribute || entry.category == attribute) {
 hasAttribute = true;
 break;
 }
 }
 if (!hasAttribute) {
 isMatch = false;
 break;
 }
 }
 if (isMatch) {
 matchingExcursions.push_back(excursion);
 }
 }
 return matchingExcursions;
 }
};

