import (
 "strings"
)
func extractFeatures(text string) []float64 {
 // Convert text to lowercase and split into words
 words := strings.Split(strings.ToLower(text), " ")
 // Define a vocabulary of words
 vocab := map[string]int{
 "reset": 1,
 "password": 2,
 "team": 3,
 "available": 4,
 "help": 5,
 "account": 6,
 "change": 7,
 "subscription": 8,
 "plan": 9,
 "business": 10,
 "hours": 11,
 "billing": 12,
 "question": 13,
 "assist": 14,
 "technical": 15,
 "cancel": 16,
 "services": 17,
 "offer": 18,
 }
 // Create a bag-of-words vector
 var features []float64
 for i := 1; i <= len(vocab); i++ {
 if contains(words, i) {
 features = append(features, 1)
 } else {
 features = append(features, 0)
 }
 }
 return features
}
// Helper function to check if a word is in the vocabulary
func contains(words []string, wordIndex int) bool {
 for _, word := range words {
 if vocab[word] == wordIndex {
 return true
 }
 }
 return false
}
