registers:
 - DISP\_CTRL: { addr: 0x10 , type: uint8\_t, perm: rw, default: 0x08, desc: Display Control} 
 - CONTRAST: { addr: 0x11 , type: uint8\_t, perm: rw, default: 0x40, desc: Contrast} 
 - SUB\_CONTRAST\_R: { addr: 0x12 , type: uint8\_t, perm: rw, default: 0x40, desc: Contrast sub R} 
 - SUB\_CONTRAST\_B: { addr: 0x13 , type: uint8\_t, perm: rw, default: 0x40, desc: Contrast sub B} 
 - BRIGHTNESS: { addr: 0x14 , type: uint8\_t, perm: rw, default: 0x40, desc: Brightness} 
 - SUB\_BRIGHTNESS\_R: { addr: 0x15 , type: uint8\_t, perm: rw, default: 0x40, desc: Brightness R} 
 - SUB\_BRIGHTNESS\_B: { addr: 0x16 , type: uint8\_t, perm: rw, default: 0x40, desc: Brightness B} 
 - H\_BLANKING: { addr: 0x17 , type: uint8\_t, perm: rw, default: 0x40, desc: Brightness B} 
 - V\_BLANKING: { addr: 0x18 , type: uint8\_t, perm: rw, default: 0x40, desc: Brightness B} 
 - DISPLAY\_MODE: { addr: 0x19 , type: uint8\_t, perm: rw, default: 0x6D, desc: Display Mode settings} 
 - BIST\_FNCTN\_SETTING: { addr: 0x1C , type: uint8\_t, perm: rw, default: 0x38, desc: BIST Fumction Setting} 


###########################################################################################################
# Fields #
###########################################################################################################
fields:
 - DISP\_CTRL: 
 - GRB: {bit: 3, desc: Resets all register settings}
 - DISP:
 bit: 0
 desc: Display Mode 
 values:
 - NORMAL: {val: 1, desc: Normal display mode }
 - STANDBY: {val: 0, desc: Standby mode }

 - DISPLAY\_MODE: #create flags and fields in the DUMMY register
 - MVA\_TN:
 bit: 7
 desc: TN v VA mode select
 values: 
 - TN: {val: 0, desc: TN mode}
 - VA: {val: 1, desc: VA mode}

 - VDIR: 
 bit: 6
 desc: Vertical Scan Direction
 values: 
 - B2T: {val: 0, desc: Bottom To Top}
 - T2B: {val: 1, desc: Top to bottom}

 - HDIR: 
 bit: 5 
 desc: Horizontal Scan Direction
 values: 
 - R2L: {val: 0, desc: Right to left}
 - L2R: {val: 1, desc: Left to Right}
 - VDPOL: 
 bit: 3 
 desc: VSYNC Polarity
 values: 
 - POS: {val: 0, desc: Positive Polarity}
 - NEG: {val: 1, desc: Negative Polarity}
 - HDPOL: 
 bit: 2 
 desc: HSYNC Polarity
 values: 
 - POS: {val: 0, desc: Positive Polarity}
 - NEG: {val: 1, desc: Positive Polarity}

 - DEPOL: 
 bit: 1
 desc: DE Polarity
 values: 
 - POS: {val: 0, desc: Positive Polarity}
 - NEG: {val: 1, desc: Positive Polarity}

 - DCLKPOL: 
 bit: 0 
 desc: DCLK Polarity
 values: 
 - POS: {val: 0, desc: Positive Polarity}
 - NEG: {val: 1, desc: Positive Polarity}

 - BIST\_FNCTN\_SETTING:

 - PICSEC:
 mask: 0x60
 desc: Time interval of test pattern 
 values: 
 - 500MS: {val: 0, desc: 500 ms}
 - 1000MS: {val: 1, desc: 1000 ms}
 - 1500MS: {val: 2, desc: 1500 ms}
 - 2000MS: {val: 3, desc: 2000 ms}

 - AUTOBIST: {bit: 3, desc: Auto display pattern control in the BIST mode }

###########################################################################################################
