onChangeAmount(isPositive: boolean): void {
const currentIndex = this.amountList.indexOf(this.amount);
if (isPositive) {
this.amount = this.amountList[currentIndex + 1] || this.amount;
return;
}

this.amount = this.amountList[currentIndex - 1] || this.amount;
}

startPayment(isRouteCheck?: boolean): void {
if (this.selectedMethod === PaymentMethods.giftcards) {
this.amountList = [10, 25, 50, 100, 200];
this.depositTitle = ‘DEPOSIT.SELECT\_GIFTCARD’;
} else {
this.amountList = [...this.initialAmountList];
}

if (this.selectedMethod !== PaymentMethods.giftcards) {
this.depositTitle = ‘DEPOSIT.SELECT\_YOUR\_AMOUNT’;
}

this.paymentOption = this.selectedMethod;

if (!isRouteCheck) {
this.languageRouter.navigate([‘/topup’], {
