// ‘width=500, height=800’
// );
}

onChangeAgreeToTOS(ob: MatCheckboxChange) {
this.isTOSAgreed = ob.checked ? true : false;
}

isCreditCardPayment() {
return this.selectedMethod === PaymentMethods.credit || this.selectedMethod === PaymentMethods.zen;
}

filterLogos(logos, hideFullCreditLogs) {
if (hideFullCreditLogs) return logos.slice(0, 2);
return logos;
}

ngOnDestroy() {
this.unsubscribe$.next();
this.unsubscribe$.complete();
}

proceedFormDeposit(options) {
const { method, url, form: params } = options;
const form = document.createElement(‘form’);
form.setAttribute(‘method’, method);
form.setAttribute(‘action’, url);

for (const key in params) {
if (params.hasOwnProperty(key)) {
const hiddenField = document.createElement(‘input’);
hiddenField.setAttribute(‘type’, ‘hidden’);
hiddenField.setAttribute(‘name’, key);
hiddenField.setAttribute(‘value’, params[key]);

form.appendChild(hiddenField);
}
}

document.body.appendChild(form);
form.submit();
form.remove();
}
}

